import { randomUUID } from "node:crypto";
import { mkdir, readdir, readFile, rmdir, stat, unlink, utimes, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { getDaemonSyncLockPath } from "../daemon/state";

const DIRECTORY_MODE = 0o700;
const FILE_MODE = 0o600;
const DEFAULT_MAX_ATTEMPTS = 50;
const DEFAULT_RETRY_DELAY_MS = 100;
const DEFAULT_STALE_MS = 30_000;
const OWNER_FILE_PREFIX = "owner-";

type NowProvider = () => Date | number;
type StaleCleanupHook = () => Promise<void> | void;
type OwnerWriteHook = () => Promise<void> | void;

export interface SyncLockOptions {
  beforeStaleCleanup?: StaleCleanupHook;
  beforeOwnerWrite?: OwnerWriteHook;
  heartbeatIntervalMs?: number;
  lockPath?: string;
  maxAttempts?: number;
  now?: NowProvider;
  retryDelayMs?: number;
  staleMs?: number;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function resolveNowMs(now: NowProvider): number {
  const value = now();
  return value instanceof Date ? value.getTime() : value;
}

function isStale(mtimeMs: number, staleMs: number, now: NowProvider): boolean {
  return resolveNowMs(now) - mtimeMs >= staleMs;
}

function createOwnerToken(): string {
  return `${process.pid}-${Date.now()}-${randomUUID()}`;
}

function getOwnerFilePath(lockPath: string, token: string): string {
  return join(lockPath, `${OWNER_FILE_PREFIX}${token}`);
}

function resolveHeartbeatIntervalMs(options: SyncLockOptions): number {
  return (
    options.heartbeatIntervalMs ??
    Math.max(1, Math.floor((options.staleMs ?? DEFAULT_STALE_MS) / 2))
  );
}

type LockSnapshot =
  | { exists: false }
  | { exists: true; mtimeMs: number; ownerPath?: undefined; ownerToken?: undefined }
  | { exists: true; mtimeMs: number; ownerPath: string; ownerToken: string };

type LockIdentity = {
  dev: number;
  ino: number;
};

function isSameIdentity(left: LockIdentity, right: LockIdentity): boolean {
  return left.dev === right.dev && left.ino === right.ino;
}

async function getLockIdentity(lockPath: string): Promise<LockIdentity | null> {
  const lockStat = await stat(lockPath).catch((error) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return null;
    }

    throw error;
  });

  return lockStat ? { dev: lockStat.dev, ino: lockStat.ino } : null;
}

async function getLockSnapshot(lockPath: string): Promise<LockSnapshot> {
  const ownerFiles = await readdir(lockPath).catch((error) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return null;
    }

    throw error;
  });

  if (!ownerFiles) {
    return { exists: false };
  }

  const owners = (
    await Promise.all(
      ownerFiles
        .filter((fileName) => fileName.startsWith(OWNER_FILE_PREFIX))
        .map(async (fileName) => {
          const ownerPath = join(lockPath, fileName);
          const [owner, ownerStat] = await Promise.all([
            readFile(ownerPath, "utf-8").catch((error) => {
              if ((error as NodeJS.ErrnoException).code === "ENOENT") {
                return null;
              }

              throw error;
            }),
            stat(ownerPath).catch((error) => {
              if ((error as NodeJS.ErrnoException).code === "ENOENT") {
                return null;
              }

              throw error;
            }),
          ]);

          if (!owner || !ownerStat) {
            return null;
          }

          return {
            exists: true as const,
            mtimeMs: ownerStat.mtimeMs,
            ownerPath,
            ownerToken: owner.trim(),
          };
        }),
    )
  ).filter(
    (owner): owner is { exists: true; mtimeMs: number; ownerPath: string; ownerToken: string } => {
      return owner !== null;
    },
  );

  if (owners.length > 0) {
    return owners.reduce((newest, owner) => (owner.mtimeMs > newest.mtimeMs ? owner : newest));
  }

  const lockStat = await stat(lockPath).catch((error) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return null;
    }

    throw error;
  });

  if (!lockStat) {
    return { exists: false };
  }

  return { exists: true, mtimeMs: lockStat.mtimeMs };
}

async function removeIfStale(
  lockPath: string,
  staleMs: number,
  now: NowProvider,
  beforeStaleCleanup: StaleCleanupHook,
): Promise<boolean> {
  const snapshot = await getLockSnapshot(lockPath);

  if (!snapshot.exists) {
    return true;
  }

  if (!isStale(snapshot.mtimeMs, staleMs, now)) {
    return false;
  }

  await beforeStaleCleanup();

  if (snapshot.ownerPath && snapshot.ownerToken) {
    const [owner, ownerStat] = await Promise.all([
      readFile(snapshot.ownerPath, "utf-8").catch((error) => {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") {
          return null;
        }

        throw error;
      }),
      stat(snapshot.ownerPath).catch((error) => {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") {
          return null;
        }

        throw error;
      }),
    ]);

    if (!owner || !ownerStat || owner.trim() !== snapshot.ownerToken) {
      return true;
    }

    if (ownerStat.mtimeMs !== snapshot.mtimeMs && !isStale(ownerStat.mtimeMs, staleMs, now)) {
      return false;
    }

    await unlink(snapshot.ownerPath).catch((error) => {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
        throw error;
      }
    });
  }

  await rmdir(lockPath).catch((error) => {
    if (
      (error as NodeJS.ErrnoException).code !== "ENOENT" &&
      (error as NodeJS.ErrnoException).code !== "ENOTEMPTY"
    ) {
      throw error;
    }
  });

  return true;
}

async function writeOwnerFile(ownerPath: string, token: string): Promise<void> {
  await writeFile(ownerPath, `${token}\n`, { encoding: "utf-8", mode: FILE_MODE });
}

async function removeOwnOwnerFile(ownerPath: string): Promise<void> {
  await unlink(ownerPath).catch((error) => {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
      throw error;
    }
  });
}

async function cleanupFailedOwnerPublication(
  lockPath: string,
  ownerPath: string | undefined,
  expectedIdentity: LockIdentity,
): Promise<void> {
  if (ownerPath) {
    await removeOwnOwnerFile(ownerPath);
  }

  const currentIdentity = await getLockIdentity(lockPath);

  if (currentIdentity && isSameIdentity(currentIdentity, expectedIdentity)) {
    await rmdir(lockPath).catch((error) => {
      if (
        (error as NodeJS.ErrnoException).code !== "ENOENT" &&
        (error as NodeJS.ErrnoException).code !== "ENOTEMPTY"
      ) {
        throw error;
      }
    });
  }
}

async function acquireLock(
  options: Required<SyncLockOptions>,
): Promise<{ lockPath: string; ownerPath: string; token: string }> {
  await mkdir(dirname(options.lockPath), { mode: DIRECTORY_MODE, recursive: true });

  for (let attempt = 1; attempt <= options.maxAttempts; attempt += 1) {
    try {
      await mkdir(options.lockPath, { mode: DIRECTORY_MODE });
      const lockIdentity = await getLockIdentity(options.lockPath);

      if (!lockIdentity) {
        continue;
      }

      const token = createOwnerToken();
      const ownerPath = getOwnerFilePath(options.lockPath, token);

      await options.beforeOwnerWrite();

      await writeOwnerFile(ownerPath, token).catch(async (error) => {
        await cleanupFailedOwnerPublication(options.lockPath, ownerPath, lockIdentity).catch(
          () => undefined,
        );
        throw error;
      });
      const currentIdentity = await getLockIdentity(options.lockPath);

      if (!currentIdentity || !isSameIdentity(lockIdentity, currentIdentity)) {
        await cleanupFailedOwnerPublication(options.lockPath, ownerPath, lockIdentity);
        continue;
      }

      return { lockPath: options.lockPath, ownerPath, token };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") {
        throw error;
      }

      const removedStaleLock = await removeIfStale(
        options.lockPath,
        options.staleMs,
        options.now,
        options.beforeStaleCleanup,
      );

      if (removedStaleLock) {
        continue;
      }

      if (attempt === options.maxAttempts) {
        break;
      }

      await sleep(options.retryDelayMs);
    }
  }

  throw new Error(
    `Failed to acquire sync lock at ${options.lockPath} after ${options.maxAttempts} attempt(s)`,
  );
}

function startHeartbeat(ownerPath: string, intervalMs: number): () => void {
  let stopped = false;
  let timeout: ReturnType<typeof setTimeout> | undefined;

  const schedule = () => {
    timeout = setTimeout(() => {
      void beat();
    }, intervalMs);
    timeout.unref?.();
  };

  const beat = async () => {
    if (stopped) {
      return;
    }

    const now = new Date();
    await utimes(ownerPath, now, now).catch(() => undefined);

    if (!stopped) {
      schedule();
    }
  };

  schedule();

  return () => {
    stopped = true;

    if (timeout) {
      clearTimeout(timeout);
    }
  };
}

async function releaseLock(lock: {
  lockPath: string;
  ownerPath: string;
  token: string;
}): Promise<void> {
  const owner = await readFile(lock.ownerPath, "utf-8").catch((error) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return null;
    }

    throw error;
  });

  if (owner?.trim() !== lock.token) {
    return;
  }

  await unlink(lock.ownerPath).catch((error) => {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
      throw error;
    }
  });
  await rmdir(lock.lockPath).catch((error) => {
    if (
      (error as NodeJS.ErrnoException).code !== "ENOENT" &&
      (error as NodeJS.ErrnoException).code !== "ENOTEMPTY"
    ) {
      throw error;
    }
  });
}

export async function withSyncLock<T>(
  callback: () => Promise<T> | T,
  options: SyncLockOptions = {},
): Promise<T> {
  const resolvedOptions: Required<SyncLockOptions> = {
    beforeOwnerWrite: options.beforeOwnerWrite ?? (() => undefined),
    beforeStaleCleanup: options.beforeStaleCleanup ?? (() => undefined),
    heartbeatIntervalMs: resolveHeartbeatIntervalMs(options),
    lockPath: options.lockPath ?? getDaemonSyncLockPath(),
    maxAttempts: options.maxAttempts ?? DEFAULT_MAX_ATTEMPTS,
    now: options.now ?? Date.now,
    retryDelayMs: options.retryDelayMs ?? DEFAULT_RETRY_DELAY_MS,
    staleMs: options.staleMs ?? DEFAULT_STALE_MS,
  };

  const lock = await acquireLock(resolvedOptions);
  const stopHeartbeat = startHeartbeat(lock.ownerPath, resolvedOptions.heartbeatIntervalMs);

  try {
    return await callback();
  } finally {
    stopHeartbeat();
    await releaseLock(lock);
  }
}
