import { access, readdir, stat } from "node:fs/promises";
import { basename, join, relative } from "node:path";
import { readSessionIndex } from "../collector/session-references";
import { getCodexRootDir, isAllowlistedCodexPath, resolveCodexPath } from "./paths";

export interface CodexRuntimeDiscoveryResult {
  historyPath?: string;
  sessionIndexPath?: string;
  transcriptPaths: string[];
}

export interface LocalDayWindow {
  start: Date;
  end: Date;
}

export interface CodexRuntimeDiscoveryOptions {
  localDayWindow?: LocalDayWindow;
}

async function directoryExists(path: string): Promise<boolean> {
  try {
    await readdir(path);
    return true;
  } catch {
    return false;
  }
}

async function pathExists(path: string): Promise<boolean> {
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}

export function createLocalDayWindow(now = new Date()): LocalDayWindow {
  const start = new Date(now);
  start.setHours(0, 0, 0, 0);
  const end = new Date(start);
  end.setDate(start.getDate() + 1);
  return { start, end };
}

export function isInsideWindow(
  timestamp: string | Date | undefined,
  window: LocalDayWindow,
): boolean {
  if (!timestamp) {
    return false;
  }

  const ms = timestamp instanceof Date ? timestamp.getTime() : new Date(timestamp).getTime();
  return Number.isFinite(ms) && ms >= window.start.getTime() && ms < window.end.getTime();
}

function formatDatePath(window: LocalDayWindow): string {
  const year = String(window.start.getFullYear());
  const month = String(window.start.getMonth() + 1).padStart(2, "0");
  const day = String(window.start.getDate()).padStart(2, "0");
  return join("sessions", year, month, day);
}

function isCurrentDayTranscript(path: string, rootDir: string, window: LocalDayWindow): boolean {
  const relativePath = relative(rootDir, path);
  const currentDayPrefix = `${formatDatePath(window)}/`;
  return relativePath.startsWith(currentDayPrefix);
}

function extractSessionIdFromTranscriptPath(path: string): string | undefined {
  const transcriptName = basename(path).replace(/\.jsonl$/, "");
  return transcriptName.match(/([0-9A-Z]{26})$/)?.[1];
}

async function readActiveSessionIds(
  sessionIndexPath: string,
  window: LocalDayWindow,
): Promise<Set<string>> {
  try {
    const entries = await readSessionIndex(sessionIndexPath);
    return new Set(
      entries.filter((entry) => isInsideWindow(entry.updatedAt, window)).map((entry) => entry.id),
    );
  } catch {
    return new Set();
  }
}

async function isCurrentMtime(path: string, window: LocalDayWindow): Promise<boolean> {
  try {
    const fileStat = await stat(path);
    return isInsideWindow(fileStat.mtime, window);
  } catch {
    return false;
  }
}

async function collectTranscriptPaths(
  dirPath: string,
  sessionIndexPath: string,
  window: LocalDayWindow,
): Promise<string[]> {
  const entries = await readdir(dirPath, { recursive: true, withFileTypes: true });
  const transcriptPaths: string[] = [];
  const rootDir = getCodexRootDir();
  const activeSessionIds = await readActiveSessionIds(sessionIndexPath, window);

  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith(".jsonl")) {
      continue;
    }

    const parentPath =
      typeof entry.parentPath === "string"
        ? entry.parentPath
        : "path" in entry && typeof entry.path === "string"
          ? join(dirPath, entry.path)
          : dirPath;
    const absolutePath = join(parentPath, entry.name);
    if (!isAllowlistedCodexPath(absolutePath)) {
      continue;
    }

    const sessionId = extractSessionIdFromTranscriptPath(absolutePath);
    if (
      isCurrentDayTranscript(absolutePath, rootDir, window) ||
      (sessionId !== undefined && activeSessionIds.has(sessionId)) ||
      (await isCurrentMtime(absolutePath, window))
    ) {
      transcriptPaths.push(absolutePath);
    }
  }

  return transcriptPaths.sort((left, right) => left.localeCompare(right));
}

export async function discoverCodexRuntimeFiles(
  options: CodexRuntimeDiscoveryOptions = {},
): Promise<CodexRuntimeDiscoveryResult> {
  const rootDir = getCodexRootDir();
  const transcriptDir = join(rootDir, "sessions");
  const sessionIndexPath = resolveCodexPath("session_index.jsonl");
  const localDayWindow = options.localDayWindow ?? createLocalDayWindow();
  const transcriptPaths = (await directoryExists(transcriptDir))
    ? await collectTranscriptPaths(transcriptDir, sessionIndexPath, localDayWindow)
    : [];

  const historyPath = resolveCodexPath("history.jsonl");

  return {
    ...((await pathExists(historyPath)) ? { historyPath } : {}),
    ...((await pathExists(sessionIndexPath)) ? { sessionIndexPath } : {}),
    transcriptPaths,
  };
}
