import { posix, win32 } from "node:path";

type ComparablePlatform = Extract<NodeJS.Platform, "darwin" | "linux" | "win32">;

function getPathApi(platform: ComparablePlatform) {
  return platform === "win32" ? win32 : posix;
}

function shouldFoldCase(platform: ComparablePlatform = process.platform as ComparablePlatform) {
  return platform === "darwin" || platform === "win32";
}

export function normalizeComparablePath(
  folderPath: string,
  platform: ComparablePlatform = process.platform as ComparablePlatform,
): string {
  const normalized = getPathApi(platform).resolve(folderPath);
  return shouldFoldCase(platform) ? normalized.toLowerCase() : normalized;
}

export function isPathIgnored(
  candidatePath: string,
  ignoredFolders: string[],
  platform: ComparablePlatform = process.platform as ComparablePlatform,
): boolean {
  const candidate = normalizeComparablePath(candidatePath, platform);

  return ignoredFolders.some((ignoredFolder) => {
    const ignored = normalizeComparablePath(ignoredFolder, platform);
    if (candidate === ignored) {
      return true;
    }

    const pathApi = getPathApi(platform);
    const relativePath = pathApi.relative(ignored, candidate);
    return (
      relativePath.length > 0 && !relativePath.startsWith("..") && !pathApi.isAbsolute(relativePath)
    );
  });
}

export function addIgnoredFolder(
  ignoredFolders: string[],
  folderPath: string,
  platform: ComparablePlatform = process.platform as ComparablePlatform,
): string[] {
  const normalized = normalizeComparablePath(folderPath, platform);
  const existing = ignoredFolders.map((entry) => normalizeComparablePath(entry, platform));

  if (existing.includes(normalized)) {
    return existing;
  }

  return [...existing, normalized].sort();
}

export function removeIgnoredFolder(
  ignoredFolders: string[],
  folderPath: string,
  platform: ComparablePlatform = process.platform as ComparablePlatform,
): string[] {
  const normalized = normalizeComparablePath(folderPath, platform);

  return ignoredFolders
    .map((entry) => normalizeComparablePath(entry, platform))
    .filter((entry) => entry !== normalized)
    .sort();
}
