import { appendFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import {
  createLogRotation,
  type LogRotation,
  type LogRotationConfig,
} from "@zest/plugin-common/log-rotation";
import {
  getCurrentLogFilePath,
  getEffectiveLogLevel,
  getLogsDir,
  isFileLoggingEnabled,
  LOG_PREFIX,
  LOG_RETENTION_DAYS,
  type LogLevel,
} from "./config";
import { redactLogDetails, serializeLogError } from "./redaction";

const LEVEL_ORDER: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

export interface LogOptions {
  details?: Record<string, unknown>;
  error?: unknown;
  runId?: string;
}

export interface LoggerDependencies {
  append?: typeof appendFile;
  createRotation?: (config: LogRotationConfig) => LogRotation;
  ensureDir?: typeof mkdir;
  now?: () => Date;
}

export interface CodexLogger {
  debug(component: string, event: string, options?: LogOptions): Promise<void>;
  info(component: string, event: string, options?: LogOptions): Promise<void>;
  warn(component: string, event: string, options?: LogOptions): Promise<void>;
  error(component: string, event: string, options?: LogOptions): Promise<void>;
}

function shouldLog(level: LogLevel): boolean {
  return LEVEL_ORDER[level] >= LEVEL_ORDER[getEffectiveLogLevel()];
}

export function createLogger(dependencies: LoggerDependencies = {}): CodexLogger {
  const append = dependencies.append ?? appendFile;
  const createRotation = dependencies.createRotation ?? createLogRotation;
  const ensureDir = dependencies.ensureDir ?? mkdir;
  const now = dependencies.now ?? (() => new Date());
  const rotation = createRotation({
    logsDir: getLogsDir(),
    retentionDays: LOG_RETENTION_DAYS,
  });

  async function cleanupLogs(): Promise<void> {
    await rotation.cleanupStaleLogs(LOG_PREFIX);
  }

  async function write(
    level: LogLevel,
    component: string,
    event: string,
    options: LogOptions = {},
  ) {
    if (!isFileLoggingEnabled() || !shouldLog(level)) return;

    const entry = {
      ts: now().toISOString(),
      level,
      component,
      event,
      ...(options.runId ? { runId: options.runId } : {}),
      ...(options.details ? { details: redactLogDetails(options.details) } : {}),
      ...(options.error ? { error: serializeLogError(options.error) } : {}),
    };

    try {
      const path = getCurrentLogFilePath();
      await ensureDir(dirname(path), { recursive: true, mode: 0o700 });
      await append(path, `${JSON.stringify(entry)}\n`, { encoding: "utf-8", mode: 0o600 });
      await cleanupLogs();
    } catch {
      return;
    }
  }

  return {
    debug: (component, event, options) => write("debug", component, event, options),
    info: (component, event, options) => write("info", component, event, options),
    warn: (component, event, options) => write("warn", component, event, options),
    error: (component, event, options) => write("error", component, event, options),
  };
}

export const logger = createLogger();
