import type { Session } from "@supabase/supabase-js";
import {
  clearAuthSession,
  loadAuthSession,
  type PersistedAuthSession,
  saveAuthSession,
} from "../auth/session";

type GoTrueSession = Pick<
  Session,
  "access_token" | "refresh_token" | "expires_at" | "expires_in" | "token_type" | "user"
>;

export interface SupportedStorageAdapter {
  getItem: (key: string) => Promise<string | null>;
  setItem: (key: string, value: string) => Promise<void>;
  removeItem: (key: string) => Promise<void>;
}

export function getJwtExpiresAt(token: string): number | undefined {
  const [, payload] = token.split(".");
  if (!payload) {
    return undefined;
  }

  try {
    const decoded = JSON.parse(Buffer.from(payload, "base64url").toString("utf-8")) as {
      exp?: unknown;
    };
    return typeof decoded.exp === "number" && Number.isFinite(decoded.exp)
      ? decoded.exp
      : undefined;
  } catch {
    return undefined;
  }
}

function isRefreshTokenExpired(session: PersistedAuthSession): boolean {
  return session.refreshTokenExpiresAt !== undefined && session.refreshTokenExpiresAt <= Date.now();
}

export function createGoTrueSession(session: PersistedAuthSession): GoTrueSession | null {
  if (isRefreshTokenExpired(session)) {
    return null;
  }

  const expiresAt = getJwtExpiresAt(session.accessToken) ?? 0;
  const now = Math.floor(Date.now() / 1000);

  return {
    access_token: session.accessToken,
    expires_at: expiresAt,
    expires_in: Math.max(0, expiresAt - now),
    refresh_token: session.refreshToken,
    token_type: "bearer",
    user: {
      app_metadata: {},
      aud: "authenticated",
      created_at: "",
      email: session.email,
      id: session.userId,
      user_metadata: {},
    },
  };
}

export async function persistGoTrueSession(session: Session | GoTrueSession): Promise<void> {
  if (!session.access_token || !session.refresh_token || !session.user?.id) {
    throw new Error("invalid Supabase session");
  }

  const existingSession = await loadAuthSession();
  const refreshTokenRotated =
    existingSession !== null && existingSession.refreshToken !== session.refresh_token;

  await saveAuthSession({
    accessToken: session.access_token,
    email: session.user.email || existingSession?.email || "",
    refreshToken: session.refresh_token,
    refreshTokenExpiresAt: refreshTokenRotated ? undefined : existingSession?.refreshTokenExpiresAt,
    userId: session.user.id,
    version: 1,
  });
}

export function createSessionStorageAdapter(
  isRemovalAllowed: () => boolean = () => true,
): SupportedStorageAdapter {
  return {
    async getItem(key: string): Promise<string | null> {
      if (key.endsWith("-code-verifier")) {
        return null;
      }

      const session = await loadAuthSession();
      if (!session) {
        return null;
      }

      const gotrueSession = createGoTrueSession(session);
      return gotrueSession ? JSON.stringify(gotrueSession) : null;
    },

    async removeItem(key: string): Promise<void> {
      if (key.endsWith("-code-verifier") || !isRemovalAllowed()) {
        return;
      }

      await clearAuthSession();
    },

    async setItem(key: string, value: string): Promise<void> {
      if (key.endsWith("-code-verifier")) {
        return;
      }

      let session: GoTrueSession;
      try {
        session = JSON.parse(value) as GoTrueSession;
      } catch {
        return;
      }
      await persistGoTrueSession(session);
    },
  };
}
