import { loadAuthSession, type PersistedAuthSession } from "../auth/session";
import {
  type CodexRuntimeDiscoveryOptions,
  type CodexRuntimeDiscoveryResult,
  createLocalDayWindow,
  discoverCodexRuntimeFiles,
  isInsideWindow,
  type LocalDayWindow,
} from "../codex/discovery";
import { buildSessionReferenceMap, buildSessionReferences } from "../collector/session-references";
import { readTranscripts } from "../collector/transcript-parser";
import { logger } from "../logging/logger";
import { sanitizeNormalizedPayloads } from "../privacy/sanitize";
import { isPathIgnored } from "../settings/folders";
import { type CodexPluginSettings, loadSettings } from "../settings/settings";
import type { StandupReadinessSummary } from "../standup/standup";
import type { CodexSessionReference } from "../types/codex-session-reference";
import type { CodexParsedTranscript } from "../types/codex-transcript";
import type {
  CodexPreparedTranscriptPayload,
  CodexSanitizedPayloadResult,
} from "../types/zest-payload";
import { loadWorkspaceBinding, type PersistedWorkspaceBinding } from "../workspace/binding";
import {
  buildSyncCheckpointMap,
  type CodexSessionSyncCheckpoint,
  filterPayloadToUnsyncedMessages,
  loadSyncCheckpoints,
} from "./checkpoints";
import { normalizeTranscriptsToPreparedPayloads } from "./normalize";
import { enqueueSanitizedPayloads } from "./queue";
import {
  type CodexSyncErrorType,
  type UploadQueuedTranscriptsResult,
  uploadQueuedTranscripts,
} from "./upload";

export type SyncPhase = "completed" | "queued_only";
export type SyncDeferredReason = "remote_sync_disabled";

export type SyncStandupReadinessSummary = StandupReadinessSummary;

export interface SyncResponse {
  success: boolean;
  phase?: SyncPhase;
  collection: {
    discoveredTranscripts: number;
    ignored: number;
    parsedTranscripts: number;
    queued: number;
    dropped: number;
  };
  uploaded: {
    messages: number;
    sessions: number;
  };
  deferredReason?: SyncDeferredReason;
  errorType?: CodexSyncErrorType;
  message: string;
  standupReadiness?: SyncStandupReadinessSummary;
}

export interface RunSyncDependencies {
  discover?: (options?: CodexRuntimeDiscoveryOptions) => Promise<CodexRuntimeDiscoveryResult>;
  enqueue?: (results: CodexSanitizedPayloadResult[], now?: Date) => Promise<unknown>;
  getStandupReadiness?: () => Promise<SyncStandupReadinessSummary | null>;
  loadSession?: () => Promise<PersistedAuthSession | null>;
  loadCheckpoints?: () => Promise<CodexSessionSyncCheckpoint[]>;
  loadSettings?: () => Promise<CodexPluginSettings>;
  loadWorkspace?: () => Promise<PersistedWorkspaceBinding | null>;
  readSessionReferences?: (input: {
    historyPath: string;
    sessionIndexPath: string;
  }) => Promise<CodexSessionReference[]>;
  readTranscripts?: (filePaths: string[]) => ReturnType<typeof readTranscripts>;
  sanitize?: typeof sanitizeNormalizedPayloads;
  upload?: () => Promise<UploadQueuedTranscriptsResult>;
}

function createCollectionSummary(overrides: Partial<SyncResponse["collection"]> = {}) {
  return {
    discoveredTranscripts: 0,
    dropped: 0,
    ignored: 0,
    parsedTranscripts: 0,
    queued: 0,
    ...overrides,
  };
}

function formatSyncMessage(result: {
  collection: SyncResponse["collection"];
  deferredReason?: SyncDeferredReason;
  errorType?: CodexSyncErrorType;
  phase?: SyncPhase;
  uploaded: SyncResponse["uploaded"];
}): string {
  const base = `Discovered ${result.collection.discoveredTranscripts} transcript(s), parsed ${result.collection.parsedTranscripts}, queued ${result.collection.queued}, dropped ${result.collection.dropped}.`;

  if (result.phase === "completed") {
    return `${base} Uploaded ${result.uploaded.sessions} session(s) and ${result.uploaded.messages} message(s).`;
  }

  if (result.phase === "queued_only" && result.errorType) {
    return `${base} Upload deferred: ${result.errorType}.`;
  }

  if (result.phase === "queued_only" && result.deferredReason) {
    return `${base} Upload deferred: ${result.deferredReason}.`;
  }

  return base;
}

function resolveSyncPhase(
  uploadResult: UploadQueuedTranscriptsResult,
  collection: SyncResponse["collection"],
): SyncPhase | undefined {
  if (uploadResult.success) {
    return "completed";
  }

  if (collection.queued > 0) {
    return "queued_only";
  }

  return undefined;
}

function resolveSyncMessage(input: {
  collection: SyncResponse["collection"];
  phase?: SyncPhase;
  uploadResult: UploadQueuedTranscriptsResult;
}): string {
  const { collection, phase, uploadResult } = input;

  if (uploadResult.success) {
    return formatSyncMessage({
      collection,
      phase: "completed",
      uploaded: uploadResult.uploaded,
    });
  }

  if (phase === "queued_only") {
    return formatSyncMessage({
      collection,
      errorType: uploadResult.errorType,
      phase,
      uploaded: uploadResult.uploaded,
    });
  }

  return uploadResult.error ?? "Sync failed.";
}

function resolveTranscriptCwd(transcript: CodexParsedTranscript): string | undefined {
  const turnContext = [...transcript.records]
    .reverse()
    .find((record) => record.recordType === "turn_context");

  return (
    transcript.sessionMeta?.cwd ??
    (turnContext?.recordType === "turn_context" ? turnContext.cwd : undefined)
  );
}

const CONVERSATIONAL_ROLES = new Set(["user", "assistant"]);

function isActiveTranscriptForLocalDay(
  transcript: CodexParsedTranscript,
  window: LocalDayWindow,
): boolean {
  return transcript.messages.some(
    (message) =>
      CONVERSATIONAL_ROLES.has(message.role) && isInsideWindow(message.timestamp, window),
  );
}

async function filterPreparedPayloadToUnsyncedMessages(
  prepared: CodexPreparedTranscriptPayload,
  checkpointsBySessionId?: Map<string, CodexSessionSyncCheckpoint>,
): Promise<CodexPreparedTranscriptPayload | null> {
  const filtered = await filterPayloadToUnsyncedMessages(prepared, checkpointsBySessionId);

  if (!filtered) {
    return null;
  }

  return {
    payload: filtered.payload,
    privacy: filtered.privacy,
  };
}

export async function runSync(dependencies: RunSyncDependencies = {}): Promise<SyncResponse> {
  const runId = `sync_${Date.now()}`;
  const discover = dependencies.discover ?? discoverCodexRuntimeFiles;
  const loadPluginSettings = dependencies.loadSettings ?? loadSettings;
  const loadCheckpoints = dependencies.loadCheckpoints ?? loadSyncCheckpoints;
  const loadSession = dependencies.loadSession ?? loadAuthSession;
  const loadWorkspace = dependencies.loadWorkspace ?? loadWorkspaceBinding;
  const readSessionReferences = dependencies.readSessionReferences ?? buildSessionReferences;
  const readAllTranscripts = dependencies.readTranscripts ?? readTranscripts;
  const sanitize = dependencies.sanitize ?? sanitizeNormalizedPayloads;
  const enqueue = dependencies.enqueue ?? enqueueSanitizedPayloads;
  const upload = dependencies.upload ?? (() => uploadQueuedTranscripts());
  await logger.info("sync", "sync_started", { runId });
  const settings = await loadPluginSettings();
  const localDayWindow = createLocalDayWindow();

  const runtime = await discover({ localDayWindow });
  const collection = createCollectionSummary({
    discoveredTranscripts: runtime.transcriptPaths.length,
  });

  if (runtime.transcriptPaths.length === 0) {
    const response: SyncResponse = {
      success: true,
      phase: "completed",
      collection,
      uploaded: {
        messages: 0,
        sessions: 0,
      },
      message: "Sync completed: no transcripts found.",
    };

    await logger.info("sync", "collection_completed", { runId, details: collection });
    await logger.info("sync", "sync_completed", {
      runId,
      details: { phase: response.phase, uploaded: response.uploaded, success: response.success },
    });
    return response;
  }

  const session = await loadSession();
  if (!session) {
    const response: SyncResponse = {
      success: false,
      collection,
      uploaded: {
        messages: 0,
        sessions: 0,
      },
      errorType: "not_authenticated",
      message: "Sync failed before collection: not authenticated.",
    };

    await logger.info("sync", "collection_completed", { runId, details: collection });
    await logger.info("sync", "sync_completed", {
      runId,
      details: { phase: response.phase, uploaded: response.uploaded, success: response.success },
    });
    return response;
  }

  const workspace = await loadWorkspace();
  const sessionRefs =
    runtime.sessionIndexPath && runtime.historyPath
      ? await readSessionReferences({
          historyPath: runtime.historyPath,
          sessionIndexPath: runtime.sessionIndexPath,
        })
      : [];
  const transcripts = await readAllTranscripts(runtime.transcriptPaths);
  const transcriptsForSync = transcripts.filter((transcript) => {
    const cwd = resolveTranscriptCwd(transcript);

    if (!cwd) {
      return true;
    }

    return !isPathIgnored(cwd, settings.ignoredFolders);
  });
  collection.ignored = transcripts.length - transcriptsForSync.length;
  const activeTranscripts = transcriptsForSync.filter((transcript) =>
    isActiveTranscriptForLocalDay(transcript, localDayWindow),
  );
  collection.parsedTranscripts = activeTranscripts.length;

  const prepared = normalizeTranscriptsToPreparedPayloads({
    transcripts: activeTranscripts,
    sessionRefsById: buildSessionReferenceMap(sessionRefs),
    userId: session.userId,
    workspaceId: workspace?.active.id ?? null,
  });
  const checkpointsBySessionId = buildSyncCheckpointMap(await loadCheckpoints());
  const unsyncedPrepared = (
    await Promise.all(
      prepared.map((payload) =>
        filterPreparedPayloadToUnsyncedMessages(payload, checkpointsBySessionId),
      ),
    )
  ).filter((payload): payload is CodexPreparedTranscriptPayload => payload !== null);
  const sanitized = await sanitize(unsyncedPrepared, settings.privacy);
  collection.dropped = sanitized.filter((result) => result.status === "dropped").length;
  collection.queued = sanitized.filter((result) => result.status === "sanitized").length;

  await enqueue(sanitized);
  await logger.info("sync", "collection_completed", { runId, details: collection });

  if (!settings.remoteSync.enabled) {
    const response: SyncResponse = {
      success: true,
      phase: "queued_only",
      collection,
      deferredReason: "remote_sync_disabled",
      uploaded: {
        messages: 0,
        sessions: 0,
      },
      message: formatSyncMessage({
        collection,
        deferredReason: "remote_sync_disabled",
        phase: "queued_only",
        uploaded: {
          messages: 0,
          sessions: 0,
        },
      }),
    };

    await logger.info("sync", "sync_completed", {
      runId,
      details: { phase: response.phase, uploaded: response.uploaded, success: response.success },
    });
    return response;
  }

  const uploadResult = await upload();
  const phase = resolveSyncPhase(uploadResult, collection);
  const response: SyncResponse = {
    success: uploadResult.success,
    ...(phase ? { phase } : {}),
    collection,
    uploaded: uploadResult.uploaded,
    ...(uploadResult.errorType ? { errorType: uploadResult.errorType } : {}),
    message: resolveSyncMessage({
      collection,
      phase,
      uploadResult,
    }),
  };

  if (uploadResult.success && dependencies.getStandupReadiness) {
    const readiness = await dependencies.getStandupReadiness();
    if (readiness) {
      response.standupReadiness = readiness;
    }
  }

  await logger.info("sync", "sync_completed", {
    runId,
    details: { phase: response.phase, uploaded: response.uploaded, success: response.success },
  });
  return response;
}
