import { getDatedLogPath } from "@zest/plugin-common/log-rotation";
import { resolveStatePath } from "../state/paths";

declare const __ZEST_CODEX_DISABLE_LOGS__: string | undefined;
declare const __ZEST_CODEX_LOG_LEVEL__: string | undefined;
declare const __ZEST_CODEX_ENABLE_LOGS__: string | undefined;

export type LogLevel = "debug" | "info" | "warn" | "error";

export const LOG_RETENTION_DAYS = 7;
export const LOG_PREFIX = "plugin";

const LEVELS: LogLevel[] = ["debug", "info", "warn", "error"];

function resolveConfigValue(bundledValue: string | undefined, runtimeValue: string | undefined) {
  if (typeof runtimeValue === "string" && runtimeValue.length > 0) return runtimeValue;
  if (typeof bundledValue === "string" && bundledValue.length > 0) return bundledValue;
  return "";
}

export function getLogsDir(): string {
  return resolveStatePath("logs");
}

export function isFileLoggingEnabled(): boolean {
  const disabled = resolveConfigValue(
    typeof __ZEST_CODEX_DISABLE_LOGS__ !== "undefined" ? __ZEST_CODEX_DISABLE_LOGS__ : undefined,
    process.env.ZEST_CODEX_DISABLE_LOGS,
  );
  return disabled !== "1";
}

export function getEffectiveLogLevel(): LogLevel {
  const configured = resolveConfigValue(
    typeof __ZEST_CODEX_LOG_LEVEL__ !== "undefined" ? __ZEST_CODEX_LOG_LEVEL__ : undefined,
    process.env.ZEST_CODEX_LOG_LEVEL,
  );

  if (LEVELS.includes(configured as LogLevel)) {
    return configured as LogLevel;
  }

  return "info";
}

export function isLegacyLoggingAliasEnabled(): boolean {
  return (
    resolveConfigValue(
      typeof __ZEST_CODEX_ENABLE_LOGS__ !== "undefined" ? __ZEST_CODEX_ENABLE_LOGS__ : undefined,
      process.env.ZEST_CODEX_ENABLE_LOGS,
    ) === "1"
  );
}

export function getCurrentLogFilePath(): string {
  return getDatedLogPath(getLogsDir(), LOG_PREFIX);
}
