import { basename } from "node:path";
import type { CodexSessionMetadata } from "@zest/types/session-metadata";
import type { SessionSignals } from "@zest/types/session-signals";
import { isAllowlistedCodexPath } from "../codex/paths";
import { PLATFORM_CODEX_APP, PLATFORM_TERMINAL, SOURCE } from "../config/constants";
import type { CodexSessionReference } from "../types/codex-session-reference";
import type {
  CodexParsedTranscript,
  CodexRateLimitWindow,
  CodexTokenCountEventRecord,
  CodexTokenUsage,
  CodexTranscriptMessage,
  CodexTurnContextRecord,
} from "../types/codex-transcript";
import type {
  ChatMessageInsert,
  ChatSessionInsert,
  CodexNormalizedTranscriptPayload,
  CodexPreparedTranscriptPayload,
} from "../types/zest-payload";

interface NormalizeTranscriptInput {
  transcript: CodexParsedTranscript;
  sessionRef?: CodexSessionReference;
  userId: string;
  workspaceId?: string | null;
}

interface NormalizeTranscriptsInput {
  transcripts: CodexParsedTranscript[];
  sessionRefsById?: Map<string, CodexSessionReference>;
  userId: string;
  workspaceId?: string | null;
}

function normalizeSignals(signals: SessionSignals): SessionSignals {
  return {
    mcp_usage: { ...signals.mcp_usage },
    skill_usage: {},
    agent_usage: { ...signals.agent_usage },
    builtin_usage: { ...signals.builtin_usage },
    unknown_usage: { ...signals.unknown_usage },
    image_count: signals.image_count,
  };
}

function resolveCreatedAt(transcript: CodexParsedTranscript): {
  createdAt: string;
  source: CodexNormalizedTranscriptPayload["decisions"]["createdAtSource"];
} {
  if (transcript.sessionMeta?.timestamp) {
    return { createdAt: transcript.sessionMeta.timestamp, source: "session_meta" };
  }

  const firstRecordTimestamp = transcript.records[0]?.timestamp;
  if (firstRecordTimestamp) {
    return { createdAt: firstRecordTimestamp, source: "first_record" };
  }

  return {
    createdAt: transcript.messages[0]?.timestamp ?? new Date(0).toISOString(),
    source: "first_message",
  };
}

function resolvePlatform(originator: string | undefined): {
  platform: string;
  source: CodexNormalizedTranscriptPayload["decisions"]["platformSource"];
} {
  if (originator === "Codex Desktop") {
    return {
      platform: PLATFORM_CODEX_APP,
      source: "originator",
    };
  }

  if (originator === "codex_cli_rs") {
    return {
      platform: PLATFORM_TERMINAL,
      source: "originator",
    };
  }

  return {
    platform: PLATFORM_TERMINAL,
    source: "fallback",
  };
}

function normalizeMessageContent(message: CodexTranscriptMessage): string {
  return message.textParts
    .map((part) => part.trim())
    .filter((part) => part.length > 0)
    .join("\n\n");
}

type MessageMetadata = Record<string, string | number>;

function normalizeMessageMetadata(message: CodexTranscriptMessage): MessageMetadata | null {
  const metadata: MessageMetadata = {};

  if (message.phase) {
    metadata.phase = message.phase;
  }

  metadata.source = message.source;
  metadata.line_number = message.lineNumber;

  return Object.keys(metadata).length > 0 ? metadata : null;
}

const CONVERSATIONAL_ROLES = new Set(["user", "assistant"]);

function resolveTranscriptModels(transcript: CodexParsedTranscript): string[] {
  const models = new Set<string>();

  for (const record of transcript.records) {
    if (record.recordType !== "turn_context") {
      continue;
    }

    const model = resolveTurnContextModel(record);
    if (model) {
      models.add(model);
    }
  }

  return Array.from(models);
}

function resolveTurnContextModel(record: CodexTurnContextRecord): string | null {
  if (record.model) {
    return record.model;
  }

  return record.collaborationMode?.model ?? null;
}

function resolveModelWithReasoning(transcript: CodexParsedTranscript): string | undefined {
  for (const record of transcript.records) {
    if (record.recordType !== "turn_context") {
      continue;
    }

    const model = resolveTurnContextModel(record);
    if (!model) {
      continue;
    }

    const reasoning = record.effort ?? record.collaborationMode?.reasoningEffort;
    return reasoning ? `${model}:${reasoning}` : model;
  }
}

function findLatestTokenCountRecord(
  transcript: CodexParsedTranscript,
): CodexTokenCountEventRecord | undefined {
  let latest: CodexTokenCountEventRecord | undefined;

  for (const record of transcript.records) {
    if (record.recordType === "event_msg" && record.eventType === "token_count") {
      latest = record;
    }
  }

  return latest;
}

function roundPercent(value: number): number {
  return Math.round(value * 100) / 100;
}

function remainingLimit(usedPercent: number | undefined): number | undefined {
  return usedPercent === undefined ? undefined : roundPercent(Math.max(0, 100 - usedPercent));
}

function normalizeTokenUsage(usage: CodexTokenUsage | undefined) {
  if (!usage) {
    return undefined;
  }

  const normalized = {
    ...(usage.inputTokens !== undefined ? { input_tokens: usage.inputTokens } : {}),
    ...(usage.cachedInputTokens !== undefined
      ? { cached_input_tokens: usage.cachedInputTokens }
      : {}),
    ...(usage.outputTokens !== undefined ? { output_tokens: usage.outputTokens } : {}),
    ...(usage.reasoningOutputTokens !== undefined
      ? { reasoning_output_tokens: usage.reasoningOutputTokens }
      : {}),
    ...(usage.totalTokens !== undefined ? { total_tokens: usage.totalTokens } : {}),
  };

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

function normalizeRateLimitWindow(window: CodexRateLimitWindow | undefined) {
  if (!window) {
    return undefined;
  }

  const { usedPercent, windowMinutes, resetsAt, ...rest } = window;
  const normalized = {
    ...(usedPercent !== undefined ? { used_percent: usedPercent } : {}),
    ...(windowMinutes !== undefined ? { window_minutes: windowMinutes } : {}),
    ...(resetsAt !== undefined ? { resets_at: resetsAt } : {}),
    ...rest,
  };

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

function buildCodexSessionMetadata(transcript: CodexParsedTranscript): CodexSessionMetadata | null {
  const latest = findLatestTokenCountRecord(transcript);
  if (!latest) {
    return null;
  }

  const totalUsage = latest.info?.totalTokenUsage;
  const lastUsage = latest.info?.lastTokenUsage;
  const modelContextWindow = latest.info?.modelContextWindow;
  const totalUsageSnapshot = normalizeTokenUsage(totalUsage);
  const lastUsageSnapshot = normalizeTokenUsage(lastUsage);
  const modelWithReasoning = resolveModelWithReasoning(transcript);
  const fiveHourLimit = remainingLimit(latest.rateLimits?.primary?.usedPercent);
  const weeklyLimit = remainingLimit(latest.rateLimits?.secondary?.usedPercent);
  const tokenCountLatest = {
    timestamp: latest.timestamp,
    ...(totalUsageSnapshot ? { total_token_usage: totalUsageSnapshot } : {}),
    ...(lastUsageSnapshot ? { last_token_usage: lastUsageSnapshot } : {}),
    ...(modelContextWindow !== undefined ? { model_context_window: modelContextWindow } : {}),
  };
  const primary = normalizeRateLimitWindow(latest.rateLimits?.primary);
  const secondary = normalizeRateLimitWindow(latest.rateLimits?.secondary);
  const rateLimitsLatest = latest.rateLimits
    ? {
        ...(latest.rateLimits.limitId !== undefined ? { limit_id: latest.rateLimits.limitId } : {}),
        ...(latest.rateLimits.planType !== undefined
          ? { plan_type: latest.rateLimits.planType }
          : {}),
        ...(primary ? { primary } : {}),
        ...(secondary ? { secondary } : {}),
      }
    : undefined;

  const hasTokenInfo = Object.keys(tokenCountLatest).some((key) => key !== "timestamp");
  const hasRateLimitInfo = rateLimitsLatest && Object.keys(rateLimitsLatest).length > 0;
  if (!hasTokenInfo && !hasRateLimitInfo) {
    return null;
  }

  const contextTokenUsage = lastUsage?.totalTokens ?? totalUsage?.totalTokens;
  const contextUsed =
    contextTokenUsage !== undefined && modelContextWindow && modelContextWindow > 0
      ? roundPercent((contextTokenUsage / modelContextWindow) * 100)
      : undefined;

  return {
    ...(modelWithReasoning ? { model_with_reasoning: modelWithReasoning } : {}),
    ...(contextUsed !== undefined ? { context_used: contextUsed } : {}),
    ...(contextUsed !== undefined
      ? { context_remaining: roundPercent(Math.max(0, 100 - contextUsed)) }
      : {}),
    ...(fiveHourLimit !== undefined ? { five_hour_limit: fiveHourLimit } : {}),
    ...(weeklyLimit !== undefined ? { weekly_limit: weeklyLimit } : {}),
    ...(totalUsage?.totalTokens !== undefined ? { used_tokens: totalUsage.totalTokens } : {}),
    ...(totalUsage?.inputTokens !== undefined ? { input_tokens: totalUsage.inputTokens } : {}),
    ...(totalUsage?.outputTokens !== undefined ? { output_tokens: totalUsage.outputTokens } : {}),
    ...(totalUsage?.cachedInputTokens !== undefined
      ? { cache_read_tokens: totalUsage.cachedInputTokens }
      : {}),
    ...(totalUsage?.reasoningOutputTokens !== undefined
      ? { reasoning_tokens: totalUsage.reasoningOutputTokens }
      : {}),
    ...(modelContextWindow !== undefined ? { model_context_window: modelContextWindow } : {}),
    ...(hasTokenInfo ? { token_count_latest: tokenCountLatest } : {}),
    ...(hasRateLimitInfo ? { rate_limits_latest: rateLimitsLatest } : {}),
  };
}

function normalizeMessages(transcript: CodexParsedTranscript, userId: string): ChatMessageInsert[] {
  const transcriptModels = resolveTranscriptModels(transcript);
  const primaryModel = transcriptModels[0];

  return transcript.messages
    .filter((message) => CONVERSATIONAL_ROLES.has(message.role))
    .map((message) => ({
      role: message.role,
      content: normalizeMessageContent(message),
      created_at: message.timestamp,
      session_id: transcript.sessionId,
      user_id: userId,
      code_diffs: null,
      metadata: normalizeMessageMetadataWithModel(message, primaryModel),
      imageCount: message.imageCount,
    }))
    .filter((message) => message.content.length > 0 || message.imageCount > 0)
    .map(({ imageCount: _imageCount, ...message }, index) => ({
      ...message,
      message_index: index,
    }));
}

function normalizeMessageMetadataWithModel(
  message: CodexTranscriptMessage,
  modelName?: string,
): ChatMessageInsert["metadata"] {
  const metadata = normalizeMessageMetadata(message);

  if (!modelName) {
    return metadata;
  }

  return {
    ...(metadata ?? {}),
    modelName,
  };
}

export function normalizeTranscriptToZestPayload(
  input: NormalizeTranscriptInput,
): CodexNormalizedTranscriptPayload {
  const { transcript, sessionRef, userId, workspaceId } = input;
  const { createdAt, source: createdAtSource } = resolveCreatedAt(transcript);
  const { platform, source: platformSource } = resolvePlatform(transcript.sessionMeta?.originator);
  const title = sessionRef?.title ?? null;

  const session: ChatSessionInsert = {
    id: transcript.sessionId,
    title,
    created_at: createdAt,
    user_id: userId,
    workspace_id: workspaceId ?? null,
    analysis_status: "pending",
    metadata: buildCodexSessionMetadata(transcript) as ChatSessionInsert["metadata"],
    project_id: null,
    project_name: transcript.sessionMeta?.cwd ? basename(transcript.sessionMeta.cwd) : null,
    platform,
    source: SOURCE,
    signals: normalizeSignals(transcript.signals) as unknown as ChatSessionInsert["signals"],
  };

  return {
    session,
    messages: normalizeMessages(transcript, userId),
    decisions: {
      titleSource: sessionRef?.title ? "session_index" : "missing",
      createdAtSource,
      platformSource,
      sourceDetailsOmitted: true,
    },
  };
}

export function normalizeTranscriptToPreparedPayload(
  input: NormalizeTranscriptInput,
): CodexPreparedTranscriptPayload {
  const { transcript } = input;

  return {
    payload: normalizeTranscriptToZestPayload(input),
    privacy: {
      sourceKind: "transcript",
      sourcePath: transcript.filePath,
      sourcePathAllowlisted: isAllowlistedCodexPath(transcript.filePath),
    },
  };
}

export function normalizeTranscriptsToPreparedPayloads(
  input: NormalizeTranscriptsInput,
): CodexPreparedTranscriptPayload[] {
  const { transcripts, sessionRefsById, userId, workspaceId } = input;

  return transcripts.map((transcript) =>
    normalizeTranscriptToPreparedPayload({
      transcript,
      sessionRef: sessionRefsById?.get(transcript.sessionId),
      userId,
      workspaceId,
    }),
  );
}
