import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@zest/types/database";
import { loadAuthSession, type PersistedAuthSession } from "../auth/session";
import { SUPABASE_ANON_KEY, SUPABASE_URL } from "../config/constants";
import {
  createSessionStorageAdapter,
  getJwtExpiresAt,
  persistGoTrueSession,
  type SupportedStorageAdapter,
} from "./session-storage-adapter";

// Temporary backend transport: reuses the existing Supabase write path so
// Codex can ship on the same ingestion flow as Claude. We expect to replace this
// with authenticated requests to api.meetzest.com once the dedicated API is ready.
export interface OnDemandClient {
  client: SupabaseClient<Database>;
  dispose: () => Promise<void>;
}

export interface CreateOnDemandClientOptions {
  createClientImpl?: typeof createClient<Database>;
  loadSession?: () => Promise<PersistedAuthSession | null>;
  refreshMinTtlSeconds?: number;
  supabaseAnonKey?: string;
  supabaseUrl?: string;
}

function createSupabaseClientInstance(
  createClientImpl: typeof createClient<Database>,
  supabaseUrl: string,
  supabaseAnonKey: string,
  storage: SupportedStorageAdapter,
): SupabaseClient<Database> {
  return createClientImpl(supabaseUrl, supabaseAnonKey, {
    auth: {
      autoRefreshToken: false,
      detectSessionInUrl: false,
      persistSession: true,
      storage,
    },
  });
}

function isExpiringWithin(expiresAt: number | undefined, minTtlSeconds: number): boolean {
  return expiresAt !== undefined && expiresAt - Math.floor(Date.now() / 1000) <= minTtlSeconds;
}

function isStoredAccessTokenExpiringWithin(
  session: PersistedAuthSession,
  minTtlSeconds: number,
): boolean {
  const expiresAt = getJwtExpiresAt(session.accessToken);
  return expiresAt === undefined || isExpiringWithin(expiresAt, minTtlSeconds);
}

export async function createOnDemandClient(
  options: CreateOnDemandClientOptions = {},
): Promise<OnDemandClient | null> {
  const createClientImpl = options.createClientImpl ?? createClient<Database>;
  const loadSession = options.loadSession ?? loadAuthSession;
  const refreshMinTtlSeconds = options.refreshMinTtlSeconds ?? 0;
  const supabaseUrl = options.supabaseUrl ?? SUPABASE_URL;
  const supabaseAnonKey = options.supabaseAnonKey ?? SUPABASE_ANON_KEY;

  if (!supabaseUrl || !supabaseAnonKey) {
    return null;
  }

  const session = await loadSession();
  if (!session) {
    return null;
  }

  const storage = createSessionStorageAdapter(() => false);
  const client = createSupabaseClientInstance(
    createClientImpl,
    supabaseUrl,
    supabaseAnonKey,
    storage,
  );
  const { error } = await client.auth.setSession({
    access_token: session.accessToken,
    refresh_token: session.refreshToken,
  });

  if (error) {
    await client.removeAllChannels();
    return null;
  }

  const getSession =
    typeof client.auth.getSession === "function" ? client.auth.getSession.bind(client.auth) : null;
  const activeSession = getSession ? (await getSession()).data.session : null;

  if (
    (activeSession && isExpiringWithin(activeSession.expires_at, refreshMinTtlSeconds)) ||
    isStoredAccessTokenExpiringWithin(session, refreshMinTtlSeconds)
  ) {
    const { data, error: refreshError } = await client.auth.refreshSession();

    if (refreshError || !data.session) {
      await client.removeAllChannels();
      return null;
    }

    try {
      await persistGoTrueSession(data.session);
    } catch {
      await client.removeAllChannels();
      return null;
    }
  }

  return {
    client,
    dispose: async () => {
      await client.removeAllChannels();
    },
  };
}
