import { CIRCULAR_SENTINEL, type JsonSafeValue, UNSAFE_KEY_PATTERN } from "../privacy/safe-json";

const UNSAFE_STRING_ASSIGNMENT_PATTERN =
  /(["']?\b(?:access[\s_-]?token|refresh[\s_-]?token|accessToken|refreshToken|token|secret|authorization|cookie|api[\s_-]?key|anon[\s_-]?key|refresh|password|device[\s_-]?code)\b["']?)(\s*[:=]\s*)(["']?)(Bearer\s+)?([^"',\s;}\]]+)(["']?)/gi;
const UNSAFE_STRING_PHRASE_PATTERN =
  /\b(authorization|api[\s_-]?key|anon[\s_-]?key|accessToken|refreshToken|access[\s_-]?token|refresh[\s_-]?token|device[\s_-]?code)\b(\s+)(Bearer\s+)?("[^"]*"|'[^']*'|[^\s,;]+)/gi;

const MAX_STACK_LENGTH = 2000;
export type JsonSafeLogValue = JsonSafeValue;

function redactValue(value: unknown, seen: WeakSet<object>): JsonSafeLogValue {
  if (value === null || typeof value === "number" || typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    return redactUnsafeString(value);
  }

  if (Array.isArray(value)) {
    if (seen.has(value)) {
      return CIRCULAR_SENTINEL;
    }

    seen.add(value);
    const redacted = value.map((item) => redactValue(item, seen));
    seen.delete(value);
    return redacted;
  }

  if (value instanceof Error) {
    return serializeLogError(value);
  }

  if (typeof value === "object") {
    if (seen.has(value)) {
      return CIRCULAR_SENTINEL;
    }

    return redactObject(value as Record<string, unknown>, seen);
  }

  return String(value);
}

function redactObject(
  details: Record<string, unknown>,
  seen: WeakSet<object>,
): Record<string, JsonSafeLogValue> {
  const redacted: Record<string, JsonSafeLogValue> = {};
  seen.add(details);

  for (const [key, value] of Object.entries(details)) {
    redacted[key] = UNSAFE_KEY_PATTERN.test(key) ? "[REDACTED]" : redactValue(value, seen);
  }

  seen.delete(details);
  return redacted;
}

function redactUnsafeString(value: string): string {
  return value
    .replace(
      UNSAFE_STRING_ASSIGNMENT_PATTERN,
      (
        _match,
        key: string,
        separator: string,
        openingQuote: string,
        bearer: string | undefined,
        _secret: string,
        closingQuote: string,
      ) => `${key}${separator}${openingQuote}${bearer ?? ""}[REDACTED]${closingQuote}`,
    )
    .replace(
      UNSAFE_STRING_PHRASE_PATTERN,
      (_match, key: string, separator: string, bearer: string | undefined) =>
        `${key}${separator}${bearer ?? ""}[REDACTED]`,
    );
}

export function redactLogDetails(
  details: Record<string, unknown>,
): Record<string, JsonSafeLogValue> {
  return redactObject(details, new WeakSet<object>());
}

export function serializeLogError(error: unknown): Record<string, JsonSafeLogValue> {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: redactUnsafeString(error.message),
      ...(error.stack ? { stack: redactUnsafeString(error.stack).slice(0, MAX_STACK_LENGTH) } : {}),
    };
  }

  return {
    name: "UnknownError",
    message: redactUnsafeString(String(error)),
  };
}
