import { basename } from "node:path";
import { type AuthRefreshResult, ensureAuthSessionFresh } from "../auth/refresh";
import { logger } from "../logging/logger";
import { type CodexPluginSettings, loadSettings } from "../settings/settings";
import { readJsonFile } from "../state/files";
import { withSyncLock } from "../sync/lock";
import { runSync, type SyncResponse } from "../sync/sync";
import {
  type CodexDaemonActivityState,
  type CodexDaemonStatus,
  getDaemonActivityFilePath,
  writeDaemonStatus,
} from "./state";

export const DEFAULT_DAEMON_INTERVAL_MS = 60_000;
export const DEFAULT_DAEMON_IDLE_MS = 10 * 60_000;
export const DEFAULT_DAEMON_MAX_RSS_BYTES = 512 * 1024 * 1024;

interface MemoryUsageLike {
  rss: number;
  heapUsed: number;
}

interface RunDaemonCycleDependencies {
  ensureAuthFresh?: () => Promise<AuthRefreshResult>;
  getMemoryUsage?: () => MemoryUsageLike;
  maxRssBytes?: number;
  now?: () => Date;
  runSyncOnce?: () => Promise<SyncResponse>;
  writeStatus?: (status: CodexDaemonStatus) => Promise<void>;
}

interface DefaultRunDaemonCycleDependencyOverrides {
  ensureAuthSessionFresh?: typeof ensureAuthSessionFresh;
  runSync?: typeof runSync;
  withSyncLock?: typeof withSyncLock;
}

type DefaultRunDaemonCycleDependencies = Required<
  Pick<RunDaemonCycleDependencies, "ensureAuthFresh" | "runSyncOnce">
>;

interface RunDaemonDependencies {
  idleMs?: number;
  intervalMs?: number;
  loadActivity?: () => Promise<CodexDaemonActivityState | null>;
  loadPluginSettings?: () => Promise<CodexPluginSettings>;
  now?: () => Date;
  onSignal?: (signal: NodeJS.Signals, handler: () => void) => void;
  processPid?: number;
  runCycle?: () => Promise<{ shouldExit: boolean }>;
  sleep?: (ms: number, waitUntilShutdown: Promise<void>) => Promise<void>;
  writeStatus?: (status: CodexDaemonStatus) => Promise<void>;
}

export function shouldExitForMemory(memory: MemoryUsageLike, maxRssBytes: number): boolean {
  return memory.rss > maxRssBytes;
}

export function shouldRunDaemonEntrypoint(argv = process.argv): boolean {
  const entrypoint = argv[1] ? basename(argv[1]) : "";
  return entrypoint === "daemon.js" || entrypoint === "daemon.ts";
}

export function createDefaultRunDaemonCycleDependencies(
  overrides: DefaultRunDaemonCycleDependencyOverrides = {},
): DefaultRunDaemonCycleDependencies {
  const refreshAuth = overrides.ensureAuthSessionFresh ?? ensureAuthSessionFresh;
  const sync = overrides.runSync ?? runSync;
  const lockSync = overrides.withSyncLock ?? withSyncLock;

  return {
    ensureAuthFresh: () => refreshAuth({ trigger: "daemon_cycle" }),
    runSyncOnce: () => lockSync(() => sync()),
  };
}

export async function runDaemonCycle(
  dependencies: RunDaemonCycleDependencies = {},
): Promise<{ shouldExit: boolean }> {
  const defaultDependencies = createDefaultRunDaemonCycleDependencies();
  const now = dependencies.now ?? (() => new Date());
  const getMemoryUsage = dependencies.getMemoryUsage ?? (() => process.memoryUsage());
  const maxRssBytes = dependencies.maxRssBytes ?? DEFAULT_DAEMON_MAX_RSS_BYTES;
  const ensureAuthFresh = dependencies.ensureAuthFresh ?? defaultDependencies.ensureAuthFresh;
  const runSyncOnce = dependencies.runSyncOnce ?? defaultDependencies.runSyncOnce;
  const writeStatus = dependencies.writeStatus ?? writeDaemonStatus;

  const cycleStartedAt = now().toISOString();
  const runId = `daemon_${Date.now()}`;
  await logger.info("daemon", "cycle_started", {
    runId,
    details: { pid: process.pid },
  });

  try {
    await ensureAuthFresh();
    const result = await runSyncOnce();
    const memory = getMemoryUsage();
    const exitForMemory = shouldExitForMemory(memory, maxRssBytes);
    const finishedAt = now().toISOString();

    await writeStatus({
      version: 1,
      pid: process.pid,
      running: !exitForMemory,
      lastCycleStartedAt: cycleStartedAt,
      lastCycleFinishedAt: finishedAt,
      lastHeartbeatAt: finishedAt,
      ...(result.success ? { lastSuccessAt: finishedAt } : { lastErrorAt: finishedAt }),
      ...(result.errorType ? { lastErrorType: result.errorType } : {}),
      ...(exitForMemory ? { lastExitReason: "memory_limit_exceeded" } : {}),
      memory: {
        rssBytes: memory.rss,
        heapUsedBytes: memory.heapUsed,
      },
      lastResult: {
        phase: result.phase,
        queued: result.collection.queued,
        uploadedMessages: result.uploaded.messages,
        uploadedSessions: result.uploaded.sessions,
      },
    });

    await logger.info("daemon", "cycle_finished", {
      runId,
      details: {
        heapUsedBytes: memory.heapUsed,
        rssBytes: memory.rss,
        shouldExit: exitForMemory,
      },
    });
    return { shouldExit: exitForMemory };
  } catch (error) {
    const finishedAt = now().toISOString();
    const memory = getMemoryUsage();
    const exitForMemory = shouldExitForMemory(memory, maxRssBytes);

    try {
      await writeStatus({
        version: 1,
        pid: process.pid,
        running: !exitForMemory,
        lastCycleStartedAt: cycleStartedAt,
        lastCycleFinishedAt: finishedAt,
        lastHeartbeatAt: finishedAt,
        lastErrorAt: finishedAt,
        lastErrorType: "daemon_cycle_failed",
        lastErrorMessage: error instanceof Error ? error.message : "Daemon cycle failed",
        ...(exitForMemory ? { lastExitReason: "memory_limit_exceeded" } : {}),
        memory: {
          rssBytes: memory.rss,
          heapUsedBytes: memory.heapUsed,
        },
      });
    } catch {
      return { shouldExit: true };
    }

    await logger.error("daemon", "cycle_failed", { runId, error });
    return { shouldExit: exitForMemory };
  }
}

export function runDaemonEntrypoint(): void {
  void runDaemon().catch((error) => {
    console.error("daemon fatal:", error);
    process.exitCode = 1;
  });
}

async function sleep(ms: number, waitUntilShutdown: Promise<void>): Promise<void> {
  let timeout: ReturnType<typeof setTimeout> | undefined;

  try {
    await Promise.race([
      new Promise<void>((resolve) => {
        timeout = setTimeout(resolve, ms);
      }),
      waitUntilShutdown,
    ]);
  } finally {
    if (timeout) {
      clearTimeout(timeout);
    }
  }
}

function isDaemonActivityState(value: unknown): value is CodexDaemonActivityState {
  if (!value || typeof value !== "object") return false;

  const candidate = value as Partial<CodexDaemonActivityState>;
  return (
    candidate.version === 1 &&
    typeof candidate.lastActivityAt === "string" &&
    typeof candidate.lastTrigger === "string"
  );
}

async function loadDaemonActivity(): Promise<CodexDaemonActivityState | null> {
  const activity = await readJsonFile<unknown>(getDaemonActivityFilePath()).catch(() => null);
  return isDaemonActivityState(activity) ? activity : null;
}

function isIdle(activity: CodexDaemonActivityState | null, now: Date, idleMs: number): boolean {
  if (!activity) {
    return false;
  }

  const lastActivityMs = Date.parse(activity.lastActivityAt);
  return Number.isFinite(lastActivityMs) && now.getTime() - lastActivityMs > idleMs;
}

export async function runDaemon(dependencies: RunDaemonDependencies = {}): Promise<void> {
  const idleMs = dependencies.idleMs ?? DEFAULT_DAEMON_IDLE_MS;
  const intervalMs = dependencies.intervalMs ?? DEFAULT_DAEMON_INTERVAL_MS;
  const loadActivity = dependencies.loadActivity ?? loadDaemonActivity;
  const loadPluginSettings = dependencies.loadPluginSettings ?? loadSettings;
  const now = dependencies.now ?? (() => new Date());
  const runCycle = dependencies.runCycle ?? runDaemonCycle;
  const sleepBetweenCycles = dependencies.sleep ?? sleep;
  const writeStatus = dependencies.writeStatus ?? writeDaemonStatus;
  const processPid = dependencies.processPid ?? process.pid;
  const onSignal =
    dependencies.onSignal ??
    ((signal: NodeJS.Signals, handler: () => void) => process.once(signal, handler));

  const writeIdleStatus = () =>
    writeStatus({
      version: 1,
      pid: processPid,
      running: false,
      lastExitReason: "idle",
    }).catch(() => undefined);

  const writeDisabledStatus = () =>
    writeStatus({
      version: 1,
      pid: processPid,
      running: false,
      lastExitReason: "background_sync_disabled",
    }).catch(() => undefined);

  const isBackgroundSyncEnabled = async () => {
    const settings = await loadPluginSettings();
    return settings.backgroundSync.enabled;
  };

  let shuttingDown = false;
  let resolveShutdown: (() => void) | undefined;
  const waitUntilShutdown = new Promise<void>((resolve) => {
    resolveShutdown = resolve;
  });

  onSignal("SIGTERM", () => {
    shuttingDown = true;
    resolveShutdown?.();
  });

  while (!shuttingDown) {
    if (!(await isBackgroundSyncEnabled())) {
      await writeDisabledStatus();
      return;
    }

    const result = await runCycle();
    if (result.shouldExit) {
      return;
    }

    if (!(await isBackgroundSyncEnabled())) {
      await writeDisabledStatus();
      return;
    }

    if (isIdle(await loadActivity(), now(), idleMs)) {
      await writeIdleStatus();
      return;
    }

    if (!shuttingDown) {
      await sleepBetweenCycles(intervalMs, waitUntilShutdown);
    }
  }

  await writeIdleStatus();
}

if (shouldRunDaemonEntrypoint()) {
  runDaemonEntrypoint();
}
