import { logger } from "../logging/logger";
import { readJsonFile, writeJsonFileAtomic } from "../state/files";
import { resolveStatePath } from "../state/paths";
import type {
  ChatMessageInsert,
  CodexDroppedTranscriptPayload,
  CodexQueuedTranscriptPayload,
  CodexQueueEntry,
  CodexQueueStats,
  CodexSanitizedPayloadResult,
} from "../types/zest-payload";
import { isValidMessageIndex } from "./message-index";

export const MAX_RETRY_ATTEMPTS = 3;
export const FAILED_QUEUE_ENTRY_RETENTION_MS = 7 * 24 * 60 * 60 * 1000;

function getNowIso(now = new Date()): string {
  return now.toISOString();
}

function resolveQueueFilePath(): string {
  return resolveStatePath("queue", "transcripts.json");
}

function sortQueueEntries(entries: CodexQueueEntry[]): CodexQueueEntry[] {
  return [...entries].sort(
    (left, right) =>
      left.createdAt.localeCompare(right.createdAt) || left.id.localeCompare(right.id),
  );
}

function parseTimestampMs(timestamp: string | null | undefined): number | null {
  if (!timestamp) {
    return null;
  }

  const value = Date.parse(timestamp);
  return Number.isFinite(value) ? value : null;
}

function pruneFailedEntries(
  entries: CodexQueueEntry[],
  now = new Date(),
  retentionMs = FAILED_QUEUE_ENTRY_RETENTION_MS,
): CodexQueueEntry[] {
  const nowMs = now.getTime();

  return entries.filter((entry) => {
    if (entry.status !== "failed") {
      return true;
    }

    const failedAtMs =
      parseTimestampMs(entry.lastFailureAt) ??
      parseTimestampMs(entry.updatedAt) ??
      parseTimestampMs(entry.createdAt);

    if (failedAtMs === null) {
      return true;
    }

    return nowMs - failedAtMs <= retentionMs;
  });
}

function dedupeDroppedPayloads(
  results: CodexSanitizedPayloadResult[],
): CodexQueuedTranscriptPayload[] {
  return results.filter(
    (result): result is Exclude<CodexSanitizedPayloadResult, CodexDroppedTranscriptPayload> =>
      result.status === "sanitized",
  );
}

function getValidMessageIndex(message: ChatMessageInsert): number | null {
  return isValidMessageIndex(message.message_index) ? message.message_index : null;
}

function mergeQueuedTranscriptPayload(
  existingPayload: CodexQueuedTranscriptPayload,
  incomingPayload: CodexQueuedTranscriptPayload,
): CodexQueuedTranscriptPayload {
  const messagesByIndex = new Map<number, ChatMessageInsert>();

  for (const message of existingPayload.payload.messages) {
    const messageIndex = getValidMessageIndex(message);
    if (messageIndex === null) {
      continue;
    }

    messagesByIndex.set(messageIndex, message);
  }

  for (const message of incomingPayload.payload.messages) {
    const messageIndex = getValidMessageIndex(message);
    if (messageIndex === null || messagesByIndex.has(messageIndex)) {
      continue;
    }

    messagesByIndex.set(messageIndex, message);
  }

  return {
    ...incomingPayload,
    payload: {
      ...incomingPayload.payload,
      messages: [...messagesByIndex.entries()]
        .sort(([leftIndex], [rightIndex]) => leftIndex - rightIndex)
        .map(([, message]) => message),
    },
  };
}

function mergeQueueEntry(
  existingEntry: CodexQueueEntry,
  incomingPayload: CodexQueuedTranscriptPayload,
  now: Date,
): CodexQueueEntry {
  return {
    ...existingEntry,
    status: "pending",
    attemptCount: 0,
    lastError: null,
    updatedAt: getNowIso(now),
    payload: mergeQueuedTranscriptPayload(existingEntry.payload, incomingPayload),
  };
}

function getReplayKeySuffix(payload: CodexQueuedTranscriptPayload, now: Date): string {
  const messageIndexes = payload.payload.messages
    .map(getValidMessageIndex)
    .filter((messageIndex): messageIndex is number => messageIndex !== null)
    .sort((leftIndex, rightIndex) => leftIndex - rightIndex);

  return messageIndexes.length > 0 ? messageIndexes.join("-") : getNowIso(now);
}

function createFailedReplayQueueEntry(
  payload: CodexQueuedTranscriptPayload,
  now: Date,
): CodexQueueEntry {
  const entry = createQueueEntry(payload, now);
  const replayKey = `${entry.dedupeKey}:failed-replay:${getReplayKeySuffix(payload, now)}`;

  return {
    ...entry,
    id: replayKey,
    dedupeKey: replayKey,
  };
}

export function getQueueFilePath(): string {
  return resolveQueueFilePath();
}

export function createQueueEntry(
  payload: CodexQueuedTranscriptPayload,
  now = new Date(),
): CodexQueueEntry {
  const timestamp = getNowIso(now);
  const id = payload.payload.session.id;

  if (!id) {
    throw new Error("Queue entries require a session id");
  }

  return {
    id,
    dedupeKey: id,
    status: "pending",
    attemptCount: 0,
    lastAttemptAt: null,
    lastFailureAt: null,
    lastError: null,
    createdAt: timestamp,
    updatedAt: timestamp,
    payload,
  };
}

export function buildQueueEntriesFromResults(
  results: CodexSanitizedPayloadResult[],
  existingEntries: CodexQueueEntry[] = [],
  now = new Date(),
): CodexQueueEntry[] {
  const nextEntries = pruneFailedEntries(existingEntries, now);

  for (const payload of dedupeDroppedPayloads(results)) {
    const entry = createQueueEntry(payload, now);
    const existingEntryIndex = nextEntries.findIndex(
      (existingEntry) => existingEntry.dedupeKey === entry.dedupeKey,
    );

    if (existingEntryIndex !== -1) {
      const existingEntry = nextEntries[existingEntryIndex];
      if (existingEntry?.status === "pending" || existingEntry?.status === "retrying") {
        nextEntries[existingEntryIndex] = mergeQueueEntry(existingEntry, payload, now);
        continue;
      }

      if (existingEntry?.status === "failed") {
        const replayEntry = createFailedReplayQueueEntry(payload, now);
        const replayEntryIndex = nextEntries.findIndex(
          (existingReplayEntry) => existingReplayEntry.dedupeKey === replayEntry.dedupeKey,
        );

        if (replayEntryIndex === -1) {
          nextEntries.push(replayEntry);
          continue;
        }

        const existingReplayEntry = nextEntries[replayEntryIndex];
        if (
          existingReplayEntry?.status === "pending" ||
          existingReplayEntry?.status === "retrying"
        ) {
          nextEntries[replayEntryIndex] = mergeQueueEntry(existingReplayEntry, payload, now);
          continue;
        }
      }

      continue;
    }

    nextEntries.push(entry);
  }

  return sortQueueEntries(nextEntries);
}

export async function loadQueueEntries(): Promise<CodexQueueEntry[]> {
  const entries = await readJsonFile<CodexQueueEntry[]>(resolveQueueFilePath());
  return sortQueueEntries(entries ?? []);
}

export async function saveQueueEntries(entries: CodexQueueEntry[]): Promise<void> {
  await writeJsonFileAtomic(resolveQueueFilePath(), sortQueueEntries(entries));
}

export async function enqueueSanitizedPayloads(
  results: CodexSanitizedPayloadResult[],
  now = new Date(),
): Promise<CodexQueueEntry[]> {
  const existingEntries = await loadQueueEntries();
  const nextEntries = buildQueueEntriesFromResults(results, existingEntries, now);
  await saveQueueEntries(nextEntries);
  await logger.info("queue", "enqueue_completed", {
    details: {
      incomingResults: results.length,
      totalEntries: nextEntries.length,
      pending: nextEntries.filter((entry) => entry.status === "pending").length,
      retrying: nextEntries.filter((entry) => entry.status === "retrying").length,
      failed: nextEntries.filter((entry) => entry.status === "failed").length,
    },
  });
  return nextEntries;
}

export async function pruneExpiredFailedQueueEntries(
  now = new Date(),
  retentionMs = FAILED_QUEUE_ENTRY_RETENTION_MS,
): Promise<CodexQueueEntry[]> {
  const entries = await loadQueueEntries();
  const nextEntries = pruneFailedEntries(entries, now, retentionMs);
  await saveQueueEntries(nextEntries);
  return nextEntries;
}

export async function getReplayableQueueEntries(): Promise<CodexQueueEntry[]> {
  const entries = await loadQueueEntries();
  return entries.filter((entry) => {
    if (entry.status === "synced" || entry.status === "failed") {
      return false;
    }

    if (entry.status === "retrying") {
      return entry.attemptCount < MAX_RETRY_ATTEMPTS;
    }

    return true;
  });
}

export async function markQueueEntriesRetrying(
  ids: string[],
  error?: string | null,
  now = new Date(),
): Promise<CodexQueueEntry[]> {
  const idSet = new Set(ids);
  const timestamp = getNowIso(now);
  const entries = await loadQueueEntries();
  const nextEntries = entries.map((entry) => {
    if (!idSet.has(entry.id)) {
      return entry;
    }

    return {
      ...entry,
      status: "retrying" as const,
      attemptCount: entry.attemptCount + 1,
      lastAttemptAt: timestamp,
      lastError: error ?? entry.lastError,
      updatedAt: timestamp,
    };
  });

  await saveQueueEntries(nextEntries);
  return nextEntries;
}

export async function markQueueEntriesSynced(ids: string[]): Promise<CodexQueueEntry[]> {
  const idSet = new Set(ids);
  const entries = await pruneExpiredFailedQueueEntries();
  const nextEntries = entries.filter((entry) => !idSet.has(entry.id));
  await saveQueueEntries(nextEntries);
  return nextEntries;
}

export async function recordQueueFailure(
  ids: string[],
  error: string,
  now = new Date(),
): Promise<CodexQueueEntry[]> {
  const idSet = new Set(ids);
  const timestamp = getNowIso(now);
  const entries = await loadQueueEntries();
  const nextEntries = entries.map((entry) => {
    if (!idSet.has(entry.id)) {
      return entry;
    }

    const nextAttemptCount = entry.attemptCount + 1;

    return {
      ...entry,
      status: nextAttemptCount >= MAX_RETRY_ATTEMPTS ? ("failed" as const) : ("retrying" as const),
      attemptCount: nextAttemptCount,
      lastAttemptAt: timestamp,
      lastFailureAt: timestamp,
      lastError: error,
      updatedAt: timestamp,
    };
  });

  await saveQueueEntries(nextEntries);
  return nextEntries;
}

export async function getQueueStats(): Promise<CodexQueueStats> {
  const entries = await loadQueueEntries();

  return {
    total: entries.length,
    pending: entries.filter((entry) => entry.status === "pending").length,
    retrying: entries.filter((entry) => entry.status === "retrying").length,
    failed: entries.filter((entry) => entry.status === "failed").length,
  };
}
