import { mkdir, rmdir, stat } from "node:fs/promises";
import {
  DEFAULT_PRIVACY_SETTINGS,
  type PrivacySettings,
  PrivacySettingsSchema,
} from "@zest/privacy-redaction/manager";
import { z } from "zod";
import { readJsonFile, writeJsonFileAtomic } from "../state/files";
import { resolveStatePath } from "../state/paths";

export const CODEX_PLUGIN_SETTINGS_VERSION = 1;
const SETTINGS_LOCK_STALE_MS = 30_000;
const SETTINGS_LOCK_RETRY_DELAY_MS = 25;
const SETTINGS_LOCK_MAX_ATTEMPTS = 200;

export const CodexPluginSettingsSchema = z.object({
  backgroundSync: z
    .object({
      enabled: z.boolean(),
    })
    .default({ enabled: true }),
  ignoredFolders: z.array(z.string()),
  privacy: PrivacySettingsSchema,
  remoteSync: z.object({
    enabled: z.boolean(),
  }),
  version: z.literal(CODEX_PLUGIN_SETTINGS_VERSION),
});

export type CodexPluginSettings = z.infer<typeof CodexPluginSettingsSchema>;

export const DEFAULT_CODEX_PLUGIN_SETTINGS: CodexPluginSettings = {
  backgroundSync: { enabled: true },
  ignoredFolders: [],
  privacy: { ...DEFAULT_PRIVACY_SETTINGS },
  remoteSync: { enabled: true },
  version: CODEX_PLUGIN_SETTINGS_VERSION,
};

export function getSettingsFilePath(): string {
  return resolveStatePath("settings.json");
}

function getSettingsLockPath(): string {
  return `${getSettingsFilePath()}.lock`;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function cleanupStaleSettingsLock(lockPath: string): Promise<void> {
  const lockStat = await stat(lockPath).catch((error) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return null;
    }

    throw error;
  });

  if (!lockStat || Date.now() - lockStat.mtimeMs < SETTINGS_LOCK_STALE_MS) {
    return;
  }

  await rmdir(lockPath).catch((error) => {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
      throw error;
    }
  });
}

async function withSettingsLock<T>(callback: () => Promise<T>): Promise<T> {
  const lockPath = getSettingsLockPath();

  for (let attempt = 0; attempt < SETTINGS_LOCK_MAX_ATTEMPTS; attempt += 1) {
    await cleanupStaleSettingsLock(lockPath);

    try {
      await mkdir(lockPath, { mode: 0o700 });
      try {
        return await callback();
      } finally {
        await rmdir(lockPath).catch((error) => {
          if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
            throw error;
          }
        });
      }
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") {
        throw error;
      }

      await sleep(SETTINGS_LOCK_RETRY_DELAY_MS);
    }
  }

  throw new Error("Timed out waiting for Codex plugin settings lock.");
}

export async function loadSettings(): Promise<CodexPluginSettings> {
  const raw = await readJsonFile<unknown>(getSettingsFilePath());
  const parsed = CodexPluginSettingsSchema.safeParse(raw);

  if (!parsed.success) {
    return DEFAULT_CODEX_PLUGIN_SETTINGS;
  }

  return parsed.data;
}

export async function saveSettings(settings: CodexPluginSettings): Promise<void> {
  await writeJsonFileAtomic(getSettingsFilePath(), CodexPluginSettingsSchema.parse(settings));
}

export async function updateSettings(
  updater: (settings: CodexPluginSettings) => CodexPluginSettings,
): Promise<CodexPluginSettings> {
  return withSettingsLock(async () => {
    const next = CodexPluginSettingsSchema.parse(updater(await loadSettings()));
    await saveSettings(next);
    return next;
  });
}

export type { PrivacySettings };
