import { z } from "zod";

export interface AnthropicMessageUsage {
  input_tokens?: number;
  output_tokens?: number;
  cache_creation_input_tokens?: number;
  cache_read_input_tokens?: number;
  reasoning_tokens?: number;
  cache_creation?: {
    ephemeral_5m_input_tokens?: number;
    ephemeral_1h_input_tokens?: number;
  };
  server_tool_use?: {
    input_tokens?: number;
    output_tokens?: number;
  };
}

export const TOKEN_SOURCES = ["provider_reported"] as const;

export type TokenSource = (typeof TOKEN_SOURCES)[number];

export const COST_SOURCES = [
  "provider_reported",
  "derived_openrouter",
  "cursor_dashboard_api",
] as const;

export type CostSource = (typeof COST_SOURCES)[number];

export const SessionTokenUsageSchema = z.object({
  input_tokens: z.number().int().nonnegative(),
  output_tokens: z.number().int().nonnegative(),
  total_tokens: z.number().int().nonnegative(),
  token_source: z.enum(TOKEN_SOURCES),

  cost_usd: z.number().nonnegative().nullable().optional(),
  cost_source: z.enum(COST_SOURCES).nullable().optional(),

  cache_read_tokens: z.number().int().nonnegative().optional(),
  cache_creation_tokens: z.number().int().nonnegative().optional(),
  cache_creation_5m_tokens: z.number().int().nonnegative().optional(),
  cache_creation_1h_tokens: z.number().int().nonnegative().optional(),
  reasoning_tokens: z.number().int().nonnegative().optional(),

  server_tool_use_input_tokens: z.number().int().nonnegative().optional(),
  server_tool_use_output_tokens: z.number().int().nonnegative().optional(),

  message_count_with_tokens: z.number().int().nonnegative().optional(),

  model_usage: z
    .record(
      z.string(),
      z.object({
        input_tokens: z.number().nonnegative(),
        output_tokens: z.number().nonnegative(),
        cache_read_input_tokens: z.number().nonnegative().optional(),
        cache_creation_input_tokens: z.number().nonnegative().optional(),
        cost_usd: z.number().nonnegative().optional(),
      }),
    )
    .optional(),

  context_used_percent: z.number().nonnegative().max(100).optional(),
  context_window_size: z.number().int().nonnegative().optional(),

  rate_limit_percent: z.number().nonnegative().optional(),
  rate_limit_type: z.string().optional(),
  rate_limit_is_overage: z.boolean().optional(),
});

export type SessionTokenUsage = z.infer<typeof SessionTokenUsageSchema>;
