import { z } from "zod";

const metricChangeSchema = z.object({
  percentage: z.number(),
  label: z.string(),
});

const metricSubMetricSchema = z.object({
  name: z.string(),
  value: z.number(),
  unit: z.string(),
  change: metricChangeSchema.optional(),
});

export const metricDrilldownSchema = z.discriminatedUnion("type", [
  z.object({
    type: z.literal("gh_pull_requests"),
    filters: z.object({ state: z.enum(["merged", "closed", "open"]) }).optional(),
  }),
  z.object({
    type: z.literal("gh_issues"),
    filters: z.object({ state: z.enum(["closed", "open"]) }).optional(),
  }),
]);

export const metricItemSchema = z.object({
  name: z.string(),
  description: z.string().optional(),
  value: z.number(),
  unit: z.string(),
  trend_points: z.array(z.number().nullable()),
  ai_trend_points: z.array(z.number().nullable()).optional(),
  change: metricChangeSchema.optional(),
  sub_metrics: z.array(metricSubMetricSchema).optional(),
  drilldown: metricDrilldownSchema.optional(),
});

export const gitHubMetricsEntryDataSchema = z.object({
  metrics: z.array(metricItemSchema).min(1),
});

export type MetricItem = z.infer<typeof metricItemSchema>;
export type GitHubMetricsEntryData = z.infer<typeof gitHubMetricsEntryDataSchema>;
