import { readJsonFile, writeJsonFileAtomic } from "../state/files";
import { resolveStatePath } from "../state/paths";
import type {
  ChatMessageInsert,
  CodexNormalizedTranscriptPayload,
  CodexQueuedTranscriptPayload,
} from "../types/zest-payload";
import { isValidMessageIndex } from "./message-index";

export interface CodexSessionSyncCheckpoint {
  sessionId: string;
  lastSyncedMessageIndex: number;
  lastSyncedAt: string;
}

function resolveSyncCheckpointsFilePath(): string {
  return resolveStatePath("sync", "checkpoints.json");
}

function sortSyncCheckpoints(
  checkpoints: CodexSessionSyncCheckpoint[],
): CodexSessionSyncCheckpoint[] {
  return [...checkpoints].sort((left, right) => left.sessionId.localeCompare(right.sessionId));
}

function isValidSyncCheckpoint(checkpoint: unknown): checkpoint is CodexSessionSyncCheckpoint {
  if (!checkpoint || typeof checkpoint !== "object") {
    return false;
  }

  const { sessionId, lastSyncedMessageIndex, lastSyncedAt } = checkpoint as {
    lastSyncedAt?: unknown;
    lastSyncedMessageIndex?: unknown;
    sessionId?: unknown;
  };

  return (
    typeof sessionId === "string" &&
    sessionId.length > 0 &&
    typeof lastSyncedMessageIndex === "number" &&
    Number.isInteger(lastSyncedMessageIndex) &&
    lastSyncedMessageIndex >= 0 &&
    typeof lastSyncedAt === "string"
  );
}

function filterValidSyncCheckpoints(checkpoints: unknown): CodexSessionSyncCheckpoint[] {
  if (!Array.isArray(checkpoints)) {
    return [];
  }

  return checkpoints.filter(isValidSyncCheckpoint);
}

export async function loadSyncCheckpoints(): Promise<CodexSessionSyncCheckpoint[]> {
  const checkpoints = await readJsonFile<unknown>(resolveSyncCheckpointsFilePath());
  return sortSyncCheckpoints(filterValidSyncCheckpoints(checkpoints));
}

export async function saveSyncCheckpoints(
  checkpoints: CodexSessionSyncCheckpoint[],
): Promise<void> {
  await writeJsonFileAtomic(
    resolveSyncCheckpointsFilePath(),
    sortSyncCheckpoints(filterValidSyncCheckpoints(checkpoints)),
  );
}

export async function getLastSyncedMessageIndex(sessionId: string): Promise<number | null> {
  const checkpoints = await loadSyncCheckpoints();
  const checkpoint = checkpoints.find((entry) => entry.sessionId === sessionId);
  return checkpoint?.lastSyncedMessageIndex ?? null;
}

export function buildSyncCheckpointMap(
  checkpoints: CodexSessionSyncCheckpoint[],
): Map<string, CodexSessionSyncCheckpoint> {
  return new Map(checkpoints.map((checkpoint) => [checkpoint.sessionId, checkpoint]));
}

export async function filterPayloadToUnsyncedMessages<
  T extends { payload: CodexNormalizedTranscriptPayload },
>(payload: T, checkpointsBySessionId?: Map<string, CodexSessionSyncCheckpoint>): Promise<T | null> {
  const sessionId = payload.payload.session.id;

  if (!sessionId) {
    return payload;
  }

  const lastSyncedMessageIndex = checkpointsBySessionId
    ? (checkpointsBySessionId.get(sessionId)?.lastSyncedMessageIndex ?? null)
    : await getLastSyncedMessageIndex(sessionId);

  if (lastSyncedMessageIndex === null) {
    return payload;
  }

  const messages = payload.payload.messages.filter(
    (message) =>
      isValidMessageIndex(message.message_index) && message.message_index > lastSyncedMessageIndex,
  );

  if (messages.length === 0) {
    return null;
  }

  return {
    ...payload,
    payload: {
      ...payload.payload,
      messages,
    },
  };
}

export async function recordUploadedMessageCheckpoints(
  messages: Omit<ChatMessageInsert, "id">[],
  now = new Date(),
  candidateMessages: Omit<ChatMessageInsert, "id">[] = messages,
  accountedMessages: Omit<ChatMessageInsert, "id">[] = [],
): Promise<void> {
  const uploadedIndexesBySessionId = new Map<string, Set<number>>();
  const candidateIndexesBySessionId = new Map<string, Set<number>>();
  const accountedIndexesBySessionId = new Map<string, Set<number>>();

  for (const message of messages) {
    const sessionId = message.session_id;
    const messageIndex = message.message_index;

    if (!sessionId || !isValidMessageIndex(messageIndex)) {
      continue;
    }

    const uploadedIndexes = uploadedIndexesBySessionId.get(sessionId) ?? new Set<number>();
    uploadedIndexes.add(messageIndex);
    uploadedIndexesBySessionId.set(sessionId, uploadedIndexes);
  }

  for (const message of candidateMessages) {
    const sessionId = message.session_id;
    const messageIndex = message.message_index;

    if (!sessionId || !isValidMessageIndex(messageIndex)) {
      continue;
    }

    const candidateIndexes = candidateIndexesBySessionId.get(sessionId) ?? new Set<number>();
    candidateIndexes.add(messageIndex);
    candidateIndexesBySessionId.set(sessionId, candidateIndexes);
  }

  for (const message of accountedMessages) {
    const sessionId = message.session_id;
    const messageIndex = message.message_index;

    if (!sessionId || !isValidMessageIndex(messageIndex)) {
      continue;
    }

    const accountedIndexes = accountedIndexesBySessionId.get(sessionId) ?? new Set<number>();
    accountedIndexes.add(messageIndex);
    accountedIndexesBySessionId.set(sessionId, accountedIndexes);
  }

  if (uploadedIndexesBySessionId.size === 0 && accountedIndexesBySessionId.size === 0) {
    return;
  }

  const syncedAt = now.toISOString();
  const checkpointsBySessionId = new Map(
    (await loadSyncCheckpoints()).map((checkpoint) => [checkpoint.sessionId, checkpoint]),
  );

  const sessionIds = new Set([
    ...uploadedIndexesBySessionId.keys(),
    ...accountedIndexesBySessionId.keys(),
  ]);

  for (const sessionId of sessionIds) {
    const uploadedIndexes = uploadedIndexesBySessionId.get(sessionId) ?? new Set<number>();
    const accountedIndexes = accountedIndexesBySessionId.get(sessionId) ?? new Set<number>();
    const existing = checkpointsBySessionId.get(sessionId);
    let maxUploadedIndex = existing?.lastSyncedMessageIndex ?? -1;
    const candidateIndexes = [...(candidateIndexesBySessionId.get(sessionId) ?? uploadedIndexes)]
      .filter((index) => index > maxUploadedIndex)
      .sort((left, right) => left - right);

    for (const candidateIndex of candidateIndexes) {
      if (!uploadedIndexes.has(candidateIndex) && !accountedIndexes.has(candidateIndex)) {
        break;
      }

      maxUploadedIndex = candidateIndex;
    }

    if (maxUploadedIndex <= (existing?.lastSyncedMessageIndex ?? -1)) {
      continue;
    }

    checkpointsBySessionId.set(sessionId, {
      sessionId,
      lastSyncedMessageIndex: maxUploadedIndex,
      lastSyncedAt: syncedAt,
    });
  }

  await saveSyncCheckpoints([...checkpointsBySessionId.values()]);
}
