import { z } from "zod";

// Zod schema for CustomPromptMetadata
export const CustomPromptMetadataSchema = z.object({
  tags: z.array(z.string()).optional(),
  cascade_category: z.string().optional(),
  description: z.string().optional(),
});

export type CustomPromptMetadata = z.infer<typeof CustomPromptMetadataSchema>;

// Helper to validate metadata
export const validateCustomPromptMetadata = (data: unknown): CustomPromptMetadata => {
  return CustomPromptMetadataSchema.parse(data);
};

// Safe parser for metadata
export const safeParseCustomPromptMetadata = (data: unknown) => {
  return CustomPromptMetadataSchema.safeParse(data);
};
