import { readJsonFile, writeJsonFileAtomic } from "../state/files";
import { resolveStatePath } from "../state/paths";

export type DaemonActivityTrigger = "session_start" | "user_prompt_submit" | "stop";
export type DaemonExitReason = "idle" | "background_sync_disabled" | "memory_limit_exceeded";

export interface CodexDaemonActivityState {
  version: 1;
  lastActivityAt: string;
  lastTrigger: DaemonActivityTrigger;
}

export interface CodexDaemonMemoryStatus {
  rssBytes: number;
  heapUsedBytes: number;
}

export interface CodexDaemonStatus {
  version: 1;
  pid: number | null;
  running: boolean;
  startedAt?: string;
  lastHeartbeatAt?: string;
  lastCycleStartedAt?: string;
  lastCycleFinishedAt?: string;
  lastSuccessAt?: string;
  lastErrorAt?: string;
  lastErrorType?: string;
  lastErrorMessage?: string;
  lastExitReason?: DaemonExitReason;
  memory?: CodexDaemonMemoryStatus;
  lastResult?: {
    phase?: string;
    queued: number;
    uploadedMessages: number;
    uploadedSessions: number;
  };
}

export function getDaemonPidFilePath(): string {
  return resolveStatePath("daemon", "daemon.pid");
}

export function getDaemonActivityFilePath(): string {
  return resolveStatePath("daemon", "activity.json");
}

export function getDaemonStatusFilePath(): string {
  return resolveStatePath("daemon", "status.json");
}

export function getDaemonRestartLockPath(): string {
  return resolveStatePath("daemon", "restart.lock");
}

export function getDaemonSyncLockPath(): string {
  return resolveStatePath("daemon", "sync.lock");
}

function isDaemonStatus(value: unknown): value is CodexDaemonStatus {
  if (!value || typeof value !== "object") return false;

  const candidate = value as Partial<CodexDaemonStatus>;
  return (
    candidate.version === 1 &&
    (typeof candidate.pid === "number" || candidate.pid === null) &&
    typeof candidate.running === "boolean"
  );
}

export async function touchDaemonActivity(
  trigger: DaemonActivityTrigger,
  now = new Date(),
): Promise<CodexDaemonActivityState> {
  const state: CodexDaemonActivityState = {
    version: 1,
    lastActivityAt: now.toISOString(),
    lastTrigger: trigger,
  };

  await writeJsonFileAtomic(getDaemonActivityFilePath(), state);
  return state;
}

export async function loadDaemonStatus(): Promise<CodexDaemonStatus | null> {
  const status = await readJsonFile<unknown>(getDaemonStatusFilePath()).catch(() => null);
  return isDaemonStatus(status) ? status : null;
}

export async function writeDaemonStatus(status: CodexDaemonStatus): Promise<void> {
  await writeJsonFileAtomic(getDaemonStatusFilePath(), status);
}
