export const UNSAFE_KEY_PATTERN =
  /(access[\s_-]?token|refresh[\s_-]?token|token|secret|authorization|cookie|api[\s_-]?key|anon[\s_-]?key|refresh|password|device[\s_-]?code|payload|prompt|content|diff|stdout|stderr|output|arguments)/i;

export const CIRCULAR_SENTINEL = "[Circular]";

export type JsonSafeValue =
  | boolean
  | number
  | string
  | null
  | JsonSafeValue[]
  | { [key: string]: JsonSafeValue };
